MAKE CODE: Stepper loop on A4988
language arduino
// Stepper motor on A4988 driver: Step on pin 3, Dir on pin 2.
// Moves 800 steps forward, then 800 steps back, repeating indefinitely.
// Uses AccelStepper for smooth acceleration and deceleration.
// Wiring: STEP -> pin 3, DIR -> pin 2, ENABLE -> pin 4 (LOW to enable).
// Ensure the driver's current limit is set appropriately for the motor.
#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4;

AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  pinMode(enablePin, OUTPUT);
  digitalWrite(enablePin, LOW); // Enable the driver

  // Set speed and acceleration
  stepper.setMaxSpeed(1000); // steps per second
  stepper.setAcceleration(500); // steps per second per second

  // Initial position
  stepper.moveTo(0);
}

void loop() {
  // Move forward 800 steps
  stepper.moveTo(800);
  while (stepper.distanceToGo() > 0) {
    stepper.run();
  }

  // Move back 800 steps
  stepper.moveTo(-800);
  while (stepper.distanceToGo() > 0) {
    stepper.run();
  }
}
END

