MAKE CODE: P1AM-100: Start/Stop with Seal-In
language arduino
// P1AM-100: Motor start/stop with seal-in on Productivity1000 I/O modules.
// Slot 1: Discrete input module (or P1-08SIM simulator).
//   ch 1: Start button (NO).
//   ch 2: Stop button (NC) - On when not pressed.
// Slot 2: Discrete output module (e.g., P1-08TRS relays).
//   ch 1: Motor contactor coil.
//   ch 2: Run light (optional, not used in logic here).
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool running = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to sign on
  }
}

void loop() {
  // Read Start button (NO)
  bool startPressed = P1.readDiscrete(inSlot, 1);

  // Read Stop button (NC) - True if button is NOT pressed
  bool stopPressed = !P1.readDiscrete(inSlot, 2);

  // Read Overload (NC) - True if overload is NOT tripped (safety check)
  bool overloadOk = P1.readDiscrete(inSlot, 3);

  // Logic: Run if Start is pressed AND Stop is not pressed AND Overload is OK
  // Seal-in: If already running, keep running unless Stop or Overload trips.
  running = (startPressed || running) && stopPressed && overloadOk;

  // Write outputs
  P1.writeDiscrete(running, outSlot, 1); // Motor contactor
  P1.writeDiscrete(running, outSlot, 2); // Run light
}
END

