language st
```st
// Tank Fill Valve Control
// Logic: Valve opens when low float is detected (tank empty).
// Valve stays open until high float is detected (tank full).
// This prevents the valve from closing prematurely as the level rises.

PROGRAM TankFillValve
VAR
  lowFloat : BOOL;
  highFloat : BOOL;
  fillValve : BOOL;
END_VAR

// Initialize valve to closed state
fillValve := FALSE;

// Keep valve open if low float is active (tank is empty)
// Use OR with current state to maintain state until high float triggers
fillValve := (lowFloat OR fillValve) AND NOT highFloat;

END_PROGRAM
```

END

